import React, { useEffect, useState } from 'react';
import Button from '../common/Button';

const OutputDisplay = ({ 
  gridCells, 
  images, 
  spacing, 
  canvasRef, 
  createGridImage,
  onExportJson,
  onExportImage
}) => {
  const filledCells = gridCells.filter(cell => cell.imageId);
  const [previewImageUrl, setPreviewImageUrl] = useState(null);

  // Generate preview image when grid cells change
  useEffect(() => {
    if (filledCells.length === 0 || !canvasRef.current || typeof createGridImage !== 'function') {
      setPreviewImageUrl(null);
      return;
    }

    try {
      // Create grid image and generate preview
      const canvas = createGridImage(canvasRef.current);
      if (canvas) {
        setPreviewImageUrl(canvas.toDataURL('image/png'));
      }
    } catch (error) {
      console.error('Error generating preview:', error);
      setPreviewImageUrl(null);
    }
  }, [filledCells, createGridImage, canvasRef]);

  return (
    <div className="border border-pink-200 rounded-lg shadow-sm mb-6 overflow-hidden">
      <div className="p-3 bg-pink-100 border-b border-pink-200 font-medium flex items-center text-pink-800">
        Output & Export
      </div>

      <div className="p-4 bg-white">
        <div className="mb-4 flex items-center gap-3 flex-wrap">
          <Button
            onClick={onExportJson}
            disabled={filledCells.length === 0}
            variant="secondary"
          >
            Export JSON
          </Button>

          <Button
            onClick={onExportImage}
            disabled={filledCells.length === 0}
            variant="primary"
          >
            Export Grid Image
          </Button>

          {filledCells.length === 0 && (
            <div className="text-sm text-pink-500 ml-2">
              Add images to the grid and align them first
            </div>
          )}
        </div>

        <div className="bg-pink-50 rounded-lg p-4 max-h-60 overflow-y-auto shadow-inner border border-pink-100">
          {previewImageUrl ? (
            <div className="flex flex-col items-center">
              <p className="text-sm text-pink-600 mb-2">Preview:</p>
              <div className="border border-pink-200 bg-white p-1 rounded">
                <img 
                  src={previewImageUrl} 
                  alt="Aligned grid preview" 
                  className="max-w-full max-h-48 object-contain"
                />
              </div>
            </div>
          ) : (
            <div className="text-center text-pink-400 py-4">
              {filledCells.length > 0 
                ? "Align images to generate a preview" 
                : "Add images to the grid first"}
            </div>
          )}
        </div>

        {/* Hidden canvas for export */}
        <canvas 
          ref={canvasRef} 
          style={{ display: 'none' }} 
        />
      </div>
    </div>
  );
};

export default OutputDisplay;

import React, { useState, useEffect, useRef } from 'react';
import { Stage, Layer, Rect, Image as KonvaImage, Group } from 'react-konva';

const BoundingBoxEditor = ({ image, onUpdate }) => {
  const [stageSize, setStageSize] = useState({ width: 0, height: 0, scale: 1 });
  const [bbox, setBbox] = useState({
    x: 0, 
    y: 0, 
    width: 0, 
    height: 0
  });
  const [activeHandle, setActiveHandle] = useState(null);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [originalBbox, setOriginalBbox] = useState(null);

  const containerRef = useRef(null);
  const stageRef = useRef(null);

  // Initialize bbox state when image changes
  useEffect(() => {
    if (image) {
      // Ensure we have valid bbox data
      if (image.bbLeftOffset !== undefined && 
          image.bbTopOffset !== undefined &&
          image.bbWidth !== undefined && 
          image.bbHeight !== undefined) {
        setBbox({
          x: image.bbLeftOffset,
          y: image.bbTopOffset,
          width: image.bbWidth,
          height: image.bbHeight
        });
      } else {
        // Fallback to default values
        setBbox({
          x: Math.round(image.width * 0.1),
          y: Math.round(image.height * 0.1),
          width: Math.round(image.width * 0.8),
          height: Math.round(image.height * 0.8)
        });
      }
    }
  }, [image]);


  // Adjust stage size based on container and image
  useEffect(() => {
    const updateSize = () => {
      if (!containerRef.current || !image) return;

      const containerWidth = containerRef.current.offsetWidth;

      const imageAspect = image.width / image.height;
      const maxHeight = 500; // max height for the stage

      let stageWidth = containerWidth;
      let stageHeight = stageWidth / imageAspect;

      if (stageHeight > maxHeight) {
        stageHeight = maxHeight;
        stageWidth = stageHeight * imageAspect;
      }

      setStageSize({
        width: stageWidth,
        height: stageHeight,
        scale: stageWidth / image.width
      });
    };

    updateSize();
    window.addEventListener('resize', updateSize);

    return () => window.removeEventListener('resize', updateSize);
  }, [image]);

  // Main box drag
  const handleBoxDragStart = (e) => {
    const stage = e.target.getStage();
    const pointerPos = stage.getPointerPosition();
    const position = {
      x: (pointerPos.x / stageSize.scale),
      y: (pointerPos.y / stageSize.scale)
    };

    // Check if this is inside the bounding box
    if (
      position.x >= bbox.x &&
      position.x <= bbox.x + bbox.width &&
      position.y >= bbox.y &&
      position.y <= bbox.y + bbox.height
    ) {
      setActiveHandle('box');
      setDragStart(position);
      setOriginalBbox({...bbox});
    }

    // Check if we're on a handle
    const handleSize = 8 / stageSize.scale;
    const halfHandleSize = handleSize / 2;

    // Corner handles
    if (Math.abs(position.x - bbox.x) <= halfHandleSize && 
        Math.abs(position.y - bbox.y) <= halfHandleSize) {
      setActiveHandle('topLeft');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    if (Math.abs(position.x - (bbox.x + bbox.width)) <= halfHandleSize && 
        Math.abs(position.y - bbox.y) <= halfHandleSize) {
      setActiveHandle('topRight');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    if (Math.abs(position.x - bbox.x) <= halfHandleSize && 
        Math.abs(position.y - (bbox.y + bbox.height)) <= halfHandleSize) {
      setActiveHandle('bottomLeft');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    if (Math.abs(position.x - (bbox.x + bbox.width)) <= halfHandleSize && 
        Math.abs(position.y - (bbox.y + bbox.height)) <= halfHandleSize) {
      setActiveHandle('bottomRight');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    // Edge handles
    if (Math.abs(position.x - bbox.x) <= halfHandleSize && 
        Math.abs(position.y - (bbox.y + bbox.height/2)) <= halfHandleSize) {
      setActiveHandle('left');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    if (Math.abs(position.x - (bbox.x + bbox.width)) <= halfHandleSize && 
        Math.abs(position.y - (bbox.y + bbox.height/2)) <= halfHandleSize) {
      setActiveHandle('right');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    if (Math.abs(position.x - (bbox.x + bbox.width/2)) <= halfHandleSize && 
        Math.abs(position.y - bbox.y) <= halfHandleSize) {
      setActiveHandle('top');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }

    if (Math.abs(position.x - (bbox.x + bbox.width/2)) <= halfHandleSize && 
        Math.abs(position.y - (bbox.y + bbox.height)) <= halfHandleSize) {
      setActiveHandle('bottom');
      setDragStart(position);
      setOriginalBbox({...bbox});
      return;
    }
  };

  const handleBoxDragMove = (e) => {
    if (!activeHandle || !originalBbox) return;

    const stage = e.target.getStage();
    const pointerPos = stage.getPointerPosition();
    const position = {
      x: (pointerPos.x / stageSize.scale),
      y: (pointerPos.y / stageSize.scale)
    };

    // Calculate drag delta
    const deltaX = position.x - dragStart.x;
    const deltaY = position.y - dragStart.y;

    let newBbox = {...bbox};

    switch (activeHandle) {
      case 'box':
        newBbox = {
          ...originalBbox,
          x: originalBbox.x + deltaX,
          y: originalBbox.y + deltaY
        };
        break;
      case 'topLeft':
        newBbox = {
          x: originalBbox.x + deltaX,
          y: originalBbox.y + deltaY,
          width: originalBbox.width - deltaX,
          height: originalBbox.height - deltaY
        };
        break;
      case 'topRight':
        newBbox = {
          x: originalBbox.x,
          y: originalBbox.y + deltaY,
          width: originalBbox.width + deltaX,
          height: originalBbox.height - deltaY
        };
        break;
      case 'bottomLeft':
        newBbox = {
          x: originalBbox.x + deltaX,
          y: originalBbox.y,
          width: originalBbox.width - deltaX,
          height: originalBbox.height + deltaY
        };
        break;
      case 'bottomRight':
        newBbox = {
          x: originalBbox.x,
          y: originalBbox.y,
          width: originalBbox.width + deltaX,
          height: originalBbox.height + deltaY
        };
        break;
      case 'left':
        newBbox = {
          x: originalBbox.x + deltaX,
          y: originalBbox.y,
          width: originalBbox.width - deltaX,
          height: originalBbox.height
        };
        break;
      case 'right':
        newBbox = {
          x: originalBbox.x,
          y: originalBbox.y,
          width: originalBbox.width + deltaX,
          height: originalBbox.height
        };
        break;
      case 'top':
        newBbox = {
          x: originalBbox.x,
          y: originalBbox.y + deltaY,
          width: originalBbox.width,
          height: originalBbox.height - deltaY
        };
        break;
      case 'bottom':
        newBbox = {
          x: originalBbox.x,
          y: originalBbox.y,
          width: originalBbox.width,
          height: originalBbox.height + deltaY
        };
        break;
      default:
        break;
    }

    // Basic constraints to prevent negative dimensions during drag
    if (newBbox.width < 10) {
      if (activeHandle === 'topLeft' || activeHandle === 'bottomLeft' || activeHandle === 'left') {
        newBbox.x = originalBbox.x + originalBbox.width - 10;
        newBbox.width = 10;
      } else {
        newBbox.width = 10;
      }
    }

    if (newBbox.height < 10) {
      if (activeHandle === 'topLeft' || activeHandle === 'topRight' || activeHandle === 'top') {
        newBbox.y = originalBbox.y + originalBbox.height - 10;
        newBbox.height = 10;
      } else {
        newBbox.height = 10;
      }
    }

    // Temporary update during drag - don't apply all constraints yet
    setBbox(newBbox);
  };

  const handleBoxDragEnd = (e) => {
    if (!activeHandle) return;

    // Apply final constraints
    let finalBbox = {...bbox};

    // Make sure box is within image bounds
    if (finalBbox.x < 0) finalBbox.x = 0;
    if (finalBbox.y < 0) finalBbox.y = 0;
    if (finalBbox.x + finalBbox.width > image.width) {
      if (activeHandle === 'topLeft' || activeHandle === 'bottomLeft' || activeHandle === 'left') {
        finalBbox.x = image.width - finalBbox.width;
      } else {
        finalBbox.width = image.width - finalBbox.x;
      }
    }
    if (finalBbox.y + finalBbox.height > image.height) {
      if (activeHandle === 'topLeft' || activeHandle === 'topRight' || activeHandle === 'top') {
        finalBbox.y = image.height - finalBbox.height;
      } else {
        finalBbox.height = image.height - finalBbox.y;
      }
    }

    // Ensure minimum dimensions
    if (finalBbox.width < 10) finalBbox.width = 10;
    if (finalBbox.height < 10) finalBbox.height = 10;

    setBbox(finalBbox);

    // Update parent component
    onUpdate({
      bbLeftOffset: finalBbox.x,
      bbTopOffset: finalBbox.y,
      bbWidth: finalBbox.width,
      bbHeight: finalBbox.height
    });

    // Reset drag state
    setActiveHandle(null);
    setDragStart({ x: 0, y: 0 });
    setOriginalBbox(null);
  };

  // Handle numeric input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    const numValue = parseInt(value, 10);

    if (isNaN(numValue)) return;

    const updatedBbox = { ...bbox };
    updatedBbox[name] = numValue;

    // Apply constraints
    if (updatedBbox.x < 0) updatedBbox.x = 0;
    if (updatedBbox.y < 0) updatedBbox.y = 0;
    if (updatedBbox.width < 10) updatedBbox.width = 10;
    if (updatedBbox.height < 10) updatedBbox.height = 10;
    if (updatedBbox.x + updatedBbox.width > image.width) {
      if (name === 'x') {
        updatedBbox.x = image.width - updatedBbox.width;
      } else {
        updatedBbox.width = image.width - updatedBbox.x;
      }
    }
    if (updatedBbox.y + updatedBbox.height > image.height) {
      if (name === 'y') {
        updatedBbox.y = image.height - updatedBbox.height;
      } else {
        updatedBbox.height = image.height - updatedBbox.y;
      }
    }

    setBbox(updatedBbox);

    // Update parent component
    onUpdate({
      bbLeftOffset: updatedBbox.x,
      bbTopOffset: updatedBbox.y,
      bbWidth: updatedBbox.width,
      bbHeight: updatedBbox.height
    });
  };

  if (!image) {
    return <div className="text-center p-4">No image selected</div>;
  }

  return (
    <div className="border border-gray-200 rounded-md">
      <div className="p-2 bg-gray-100 border-b border-gray-200 font-medium">
        Bounding Box Editor: {image.filename}
      </div>

      <div className="p-4">
        <div className="mb-4 text-sm text-gray-600">
          Define the bounding box area. Drag the boxes or their handles to adjust.
        </div>

        <div 
          ref={containerRef} 
          className="border border-gray-300 rounded-md mb-4"
        >
          {stageSize.width > 0 && (
            <Stage
              ref={stageRef}
              width={stageSize.width}
              height={stageSize.height}
              scaleX={stageSize.scale}
              scaleY={stageSize.scale}
              onMouseDown={handleBoxDragStart}
              onMouseMove={handleBoxDragMove}
              onMouseUp={handleBoxDragEnd}
              onMouseLeave={handleBoxDragEnd}
            >
              <Layer>
                {/* Background Image */}
                {image.image && (
                  <KonvaImage
                    image={image.image}
                    width={image.width}
                    height={image.height}
                  />
                )}

                {/* Bounding Box */}
                <Rect
                  x={bbox.x}
                  y={bbox.y}
                  width={bbox.width}
                  height={bbox.height}
                  stroke="#ff5722"
                  strokeWidth={2 / stageSize.scale}
                  dash={[5 / stageSize.scale, 5 / stageSize.scale]}
                />

                {/* Handles */}
                {activeHandle !== 'box' && (
                  <>
                    {/* Top-left corner */}
                    <Rect
                      x={bbox.x - 4 / stageSize.scale}
                      y={bbox.y - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Top-right corner */}
                    <Rect
                      x={bbox.x + bbox.width - 4 / stageSize.scale}
                      y={bbox.y - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Bottom-left corner */}
                    <Rect
                      x={bbox.x - 4 / stageSize.scale}
                      y={bbox.y + bbox.height - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Bottom-right corner */}
                    <Rect
                      x={bbox.x + bbox.width - 4 / stageSize.scale}
                      y={bbox.y + bbox.height - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Left edge */}
                    <Rect
                      x={bbox.x - 4 / stageSize.scale}
                      y={bbox.y + bbox.height/2 - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Right edge */}
                    <Rect
                      x={bbox.x + bbox.width - 4 / stageSize.scale}
                      y={bbox.y + bbox.height/2 - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Top edge */}
                    <Rect
                      x={bbox.x + bbox.width/2 - 4 / stageSize.scale}
                      y={bbox.y - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />

                    {/* Bottom edge */}
                    <Rect
                      x={bbox.x + bbox.width/2 - 4 / stageSize.scale}
                      y={bbox.y + bbox.height - 4 / stageSize.scale}
                      width={8 / stageSize.scale}
                      height={8 / stageSize.scale}
                      fill="#ff5722"
                      stroke="white"
                      strokeWidth={1 / stageSize.scale}
                    />
                  </>
                )}
              </Layer>
            </Stage>
          )}
        </div>

        <div className="grid grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Left Offset (X)</label>
            <input
              type="number"
              name="x"
              value={Math.round(bbox.x)}
              onChange={handleInputChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Top Offset (Y)</label>
            <input
              type="number"
              name="y"
              value={Math.round(bbox.y)}
              onChange={handleInputChange}
              className="w-full px-3 py-2 border border-gray-300 rounded-md"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Width</label>
            <input
              type="number"
              name="width"
              value={Math.round(bbox.width)}
              onChange={handleInputChange}
              min="10"
              className="w-full px-3 py-2 border border-gray-300 rounded-md"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Height</label>
            <input
              type="number"
              name="height"
              value={Math.round(bbox.height)}
              onChange={handleInputChange}
              min="10"
              className="w-full px-3 py-2 border border-gray-300 rounded-md"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default BoundingBoxEditor;

import React, { useRef, useEffect } from 'react';

const ImageList = ({ 
  images, 
  selectedImageId, 
  onSelectImage, 
  showAssignedState = false,
  getAssignedState = () => false,
  allowDragDrop = false
}) => {
  const dragPreviewRef = useRef(null);

  // Create a hidden image element for drag preview
  useEffect(() => {
    if (allowDragDrop && !dragPreviewRef.current) {
      const img = document.createElement('img');
      img.style.position = 'absolute';
      img.style.top = '-9999px';
      img.style.left = '-9999px';
      img.width = 100; // Small fixed size for preview
      img.height = 100;
      document.body.appendChild(img);
      dragPreviewRef.current = img;
    }

    // Cleanup
    return () => {
      if (dragPreviewRef.current && dragPreviewRef.current.parentNode) {
        try {
          dragPreviewRef.current.parentNode.removeChild(dragPreviewRef.current);
        } catch (e) {
          console.log('Error removing drag preview element:', e);
        }
        dragPreviewRef.current = null;
      }
    };
  }, [allowDragDrop]);

  if (images.length === 0) {
    return (
      <div className="border border-pink-200 bg-pink-50 rounded-lg p-6 min-h-40 flex flex-col items-center justify-center text-pink-400">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
        </svg>
        <p className="text-pink-600 text-center font-medium">No images uploaded yet</p>
        <p className="text-pink-400 text-sm text-center mt-1">
          Upload or paste images to get started
        </p>
      </div>
    );
  }

  return (
    <div className="border border-pink-200 rounded-lg">
      <div className="p-3 bg-pink-100 border-b border-pink-200 font-medium text-pink-800 flex items-center">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
        </svg>
        Images ({images.length})
      </div>
      <div className="grid grid-cols-2 gap-3 p-3 max-h-80 overflow-y-auto">
        {images.map(image => {
          const isAssigned = showAssignedState && getAssignedState(image.id);

          return (
            <div
              key={image.id}
              className={`
                flex flex-col border rounded-lg p-2 cursor-pointer transition-all duration-200
                ${image.id === selectedImageId 
                  ? 'border-pink-500 bg-pink-50 shadow-md transform scale-[1.02]' 
                  : 'border-gray-200 hover:border-pink-300 hover:bg-pink-50'
                }
                ${isAssigned ? 'opacity-60' : ''}
              `}
              onClick={() => onSelectImage(image.id)}
              draggable={allowDragDrop ? "true" : "false"}
              onDragStart={allowDragDrop ? (e) => {
                // Set the data payload
                const data = JSON.stringify({
                  imageId: image.id,
                  type: 'image-drag'
                });
                e.dataTransfer.setData('application/json', data);
                e.dataTransfer.effectAllowed = 'copy';

                // Prepare a small preview image
                if (dragPreviewRef.current) {
                  const dragImg = dragPreviewRef.current;
                  dragImg.src = image.src;
                  e.dataTransfer.setDragImage(dragImg, 50, 50);
                }

                // Visual feedback for drag
                e.currentTarget.classList.add('opacity-50');
              } : undefined}
              onDragEnd={allowDragDrop ? (e) => {
                // Remove the dragging class
                e.currentTarget.classList.remove('opacity-50');
              } : undefined}
            >
              <div className="w-full h-20 flex items-center justify-center bg-pink-100/50 mb-2 rounded overflow-hidden">
                <img
                  src={image.src}
                  alt={image.filename}
                  className="max-w-full max-h-full object-contain"
                />
              </div>
              <div className="w-full relative">
                <div className="text-xs truncate font-medium text-pink-800" title={image.filename}>
                  {image.filename}
                </div>
                <div className="text-xs text-pink-500 mt-1 flex justify-between items-center">
                  <span>{image.width}×{image.height}px</span>
                  {isAssigned && (
                    <span className="bg-pink-200 text-pink-800 px-1 rounded text-xs">In Grid</span>
                  )}
                </div>
              </div>
              {image.id === selectedImageId && (
                <div className="absolute top-0 right-0 bg-pink-500 text-white rounded-full p-1 -mt-2 -mr-2">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

