        images={imageObjects}
        spacing={spacing}
        canvasRef={outputCanvasRef}
        createGridImage={createGridImage}
        onExportJson={handleExportJson}
        onExportImage={handleExportImage}
      />

      {alignmentLog.length > 0 && (
        <AlignmentLog log={alignmentLog} />
      )}
    </div>
  );
};

