import { useCallback } from 'react';
import { useGridContext, GRID_ACTIONS } from '../context/GridContext';
import { useImageContext } from '../context/ImageContext';
import { gridService } from '../services/gridService';

/**
 * Hook for alignment operations
 */
export function useAlignment() {
  const { state: gridState, dispatch: gridDispatch } = useGridContext();
  const { state: imageState } = useImageContext();

  const { gridCells, gridDimensions, spacing, alignmentLog, isAligned } = gridState;
  const { imageObjects } = imageState;

  /**
   * Align images in the grid
   */
  const alignImages = useCallback(() => {
    // Check if there are any images in the grid
    const filledCells = gridCells.filter(cell => cell.imageId !== null);
    if (filledCells.length === 0) {
      alert('Please add at least one image to the grid before aligning');
      return;
    }

    const { updatedGridCells, alignmentLog } = gridService.alignImages(
      gridCells,
      imageObjects,
      gridDimensions,
      spacing
    );

    // Update grid cells with alignment results
    gridDispatch({
      type: GRID_ACTIONS.UPDATE_GRID_CELLS,
      payload: updatedGridCells
    });

    // Add alignment log entries
    gridDispatch({
      type: GRID_ACTIONS.ADD_ALIGNMENT_LOG,
      payload: alignmentLog
    });

    // Set alignment status
    gridDispatch({
      type: GRID_ACTIONS.ALIGN_GRID,
      payload: true
    });
  }, [gridCells, imageObjects, gridDimensions, spacing, gridDispatch]);

  /**
   * Create a grid image for export
   * @param {HTMLCanvasElement} canvas - Canvas element to render to
   * @returns {HTMLCanvasElement} Canvas with rendered grid
   */
  const createGridImage = useCallback((canvas) => {
    if (!canvas) return null;

    try {
      return gridService.createGridImage(
        canvas,
        gridCells,
        imageObjects,
        gridDimensions,
        spacing
      );
    } catch (error) {
      console.error('Error creating grid image:', error);
      return null;
    }
  }, [gridCells, imageObjects, gridDimensions, spacing]);

  return {
    alignImages,
    createGridImage,
    alignmentLog,
    isAligned
  };
}

import { useState, useCallback, useEffect } from 'react';

/**
 * Hook for file operations like drag-and-drop and clipboard
 */
export function useFileOperations({ onFiles }) {
  const [isDragging, setIsDragging] = useState(false);

  const handleFiles = useCallback((files) => {
    const imageFiles = Array.from(files).filter(file => 
      file.type.startsWith('image/')
    );

    if (imageFiles.length > 0) {
      onFiles(imageFiles);
    }
  }, [onFiles]);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(e.dataTransfer.files);
    }
  }, [handleFiles]);

  const handleDragOver = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const handlePaste = useCallback((e) => {
    const clipboardItems = e.clipboardData.items;
    const imageItems = Array.from(clipboardItems).filter(item => 
      item.type.indexOf('image') !== -1
    );

    if (imageItems.length > 0) {
      const files = imageItems.map(item => item.getAsFile());
      handleFiles(files);
    }
  }, [handleFiles]);

  useEffect(() => {
    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [handlePaste]);

  return {
    isDragging,
    handleDrop,
    handleDragOver,
    handleDragLeave,
    handleFiles
  };
}

import { useCallback, useEffect } from 'react';
import { useGridContext, GRID_ACTIONS } from '../context/GridContext';
import { gridService } from '../services/gridService';

/**
 * Hook for grid operations
 */
export function useGridOperations() {
  const { state, dispatch } = useGridContext();
  const { gridDimensions, gridCells, selectedCellIndex, spacing } = state;

  // Ensure grid is initialized
  useEffect(() => {
    if (gridCells.length === 0) {
      const newGridCells = gridService.initializeGrid(gridDimensions);
      dispatch({ 
        type: GRID_ACTIONS.INITIALIZE_GRID, 
        payload: newGridCells 
      });
    }
  }, [gridCells.length, gridDimensions, dispatch]);

  const updateGridDimensions = useCallback((rows, cols) => {
    const newDimensions = { rows, cols };
    dispatch({ 
      type: GRID_ACTIONS.UPDATE_GRID_DIMENSIONS, 
      payload: newDimensions 
    });

    const newGridCells = gridService.initializeGrid(newDimensions);
    dispatch({ 
      type: GRID_ACTIONS.INITIALIZE_GRID, 
      payload: newGridCells 
    });
  }, [dispatch]);

  const selectCell = useCallback((index) => {
    dispatch({ 
      type: GRID_ACTIONS.SELECT_CELL, 
      payload: index 
    });
  }, [dispatch]);

  const sendImageToCell = useCallback((imageId) => {
    if (selectedCellIndex === null) return;

    dispatch({ 
      type: GRID_ACTIONS.ASSIGN_IMAGE_TO_CELL, 
      payload: {
        cellIndex: selectedCellIndex,
        imageId
      }
    });
  }, [selectedCellIndex, dispatch]);

  const clearSelectedCell = useCallback(() => {
    if (selectedCellIndex === null) return;

    dispatch({ 
      type: GRID_ACTIONS.CLEAR_CELL,
      payload: selectedCellIndex
    });
  }, [selectedCellIndex, dispatch]);

  const updateSpacing = useCallback((newSpacing) => {
    dispatch({ 
      type: GRID_ACTIONS.UPDATE_SPACING, 
      payload: newSpacing 
    });
  }, [dispatch]);

  return {
    gridDimensions,
    gridCells,
    selectedCellIndex,
    spacing,
    updateGridDimensions,
    selectCell,
    sendImageToCell,
    clearSelectedCell,
    updateSpacing
  };
}

import { useState, useCallback } from 'react';
import { imageService } from '../services/imageService';
import { useImageContext, IMAGE_ACTIONS } from '../context/ImageContext';

/**
 * Hook for image processing functionality
 */
export function useImageProcessing() {
  const [isProcessing, setIsProcessing] = useState(false);
  const [snapToEdges, setSnapToEdges] = useState(true);
  const { state, dispatch } = useImageContext();

  const processImages = useCallback(async (files) => {
    if (files.length === 0) return;

    setIsProcessing(true);

    try {
      console.log("Processing", files.length, "images with snapToEdges:", snapToEdges);
      const processedImages = await imageService.processImages(files, snapToEdges);

      if (processedImages.length > 0) {
        console.log("Processed images:", processedImages.length);
        dispatch({
          type: IMAGE_ACTIONS.ADD_IMAGES,
          payload: processedImages
        });

        // Automatically select the first image if none is currently selected
        if (!state.selectedImageId) {
          dispatch({
            type: IMAGE_ACTIONS.SELECT_IMAGE,
            payload: processedImages[0].id
          });
        }
      }

      return processedImages;
    } catch (error) {
      console.error("Error processing images:", error);
    } finally {
      setIsProcessing(false);
    }
  }, [dispatch, state.selectedImageId, snapToEdges]);

  const clearAllImages = useCallback(() => {
    // Clean up object URLs before clearing
    imageService.cleanupImages(state.imageObjects);

    dispatch({ type: IMAGE_ACTIONS.CLEAR_ALL });
  }, [dispatch, state.imageObjects]);

  const toggleSnapToEdges = useCallback((value) => {
    setSnapToEdges(value);
  }, []);

  return {
    processImages,
    clearAllImages,
    isProcessing,
    snapToEdges,
    toggleSnapToEdges
  };
}

